insert into products (id,name,sku,category,description,price_inr,mrp_inr,stock_qty,image_url,image_position,is_active,about_text,best_for,pairs_well_with,recommended_stack,highlights,details)
values ('5e0c1f2a-0d4b-4c8e-9a1f-1d1c0a000001',$c$Nutrifort Energy$c$,$c$CA-NFE-30$c$,$c$General Wellness$c$,$c$Complete energy formula for men and women with 32 nutrients for daily health and vitality.$c$,899,null,20,$c$/products/nutrifort-energy.jpg$c$,'50% 50%',true,$c$Nutrifort Energy is a complete daily energy formula for men and women: 32 essential vitamins, minerals and supporting nutrients in one tablet, built for the days when diet alone falls short.
It is made for heart health, eye health, immune health, bone health, energy release and hair, skin and nails, so one tablet with breakfast covers the everyday baseline before the day gets busy.

Uses
Daily Nutritional Baseline
Fills the common gaps in a normal diet with 32 nutrients at daily maintenance levels.
Energy and Fatigue
Supports the release of energy from food, helping to reduce tiredness and fatigue.
Immune Defence
Supplies the vitamins and minerals the immune system draws on every day.
Active Lifestyles
Supports heart, bones, vision and metabolism for people who train, travel or work long hours.

Why one complete formula?
A single, well-rounded tablet is easier to keep up than a shelf of separate bottles. Nutrifort Energy brings the daily essentials together so consistency, the thing that actually delivers results, becomes the easy option.$c$,$c$Energy • Immunity • Heart health • Eye health$c$,$c$Fish Oil Omega-3 • Calcitamin$c$,$c$AM: Nutrifort Energy • PM: Fish Oil Omega-3$c$,ARRAY[$c$32 nutrients$c$,$c$30 tablets$c$,$c$Halal certified$c$,$c$GMP facility$c$]::text[],$c${"benefits": [{"icon": "energy", "title": "Helps Reduce Fatigue", "text": "Supports energy release from food to help reduce tiredness through the day."}, {"icon": "immunity", "title": "Immune Support", "text": "Strengthens the body's natural defences with the vitamins and minerals immunity relies on."}, {"icon": "heart", "title": "Heart Health", "text": "Supports the normal function of the heart as part of an active lifestyle."}, {"icon": "vision", "title": "Eye Health", "text": "Vitamins and minerals that contribute to the maintenance of normal vision."}, {"icon": "bones", "title": "Strong Bones", "text": "Supports stronger bones and teeth alongside a calcium-rich diet."}, {"icon": "focus", "title": "Mental Focus", "text": "Key nutrients help support concentration and alertness."}, {"icon": "skin", "title": "Hair, Skin and Nails", "text": "Nourishes hair, skin and nails from within."}, {"icon": "general", "title": "Metabolism", "text": "Essential vitamins support normal metabolic activity."}], "ingredients": [{"name": "Vitamin complex", "amount": "", "purpose": "Water- and fat-soluble vitamins at daily maintenance levels for energy release, immunity, vision and skin. Amounts as printed on the pack."}, {"name": "Mineral complex", "amount": "", "purpose": "Minerals for bone strength, red blood cell formation and normal muscle and nerve function. Amounts as printed on the pack."}, {"name": "Supporting nutrients", "amount": "", "purpose": "Completes the 32-nutrient formula for heart health and everyday performance. See the pack for the full list."}], "howToUse": ["Take one tablet daily with breakfast, or as directed by a healthcare professional.", "Swallow whole with a glass of water; do not chew.", "Use every day: a multinutrient works through consistency, not single doses."], "faqs": [{"q": "Is Nutrifort Energy suitable for both men and women?", "a": "Yes. It is formulated as a complete daily formula for adult men and women."}, {"q": "Does it contain caffeine or stimulants?", "a": "No. The energy support comes from the vitamins and minerals involved in releasing energy from food, not from stimulants."}, {"q": "Can I take it with other Core Atoms formulas?", "a": "Yes. It pairs well with Fish Oil Omega-3 for heart support and Calcitamin for bone support; avoid doubling up on other multivitamins."}, {"q": "How many tablets are in a pack?", "a": "Each pack holds 30 tablets, a one-month supply at one tablet a day."}], "safetyInfo": "• Food supplement, not a substitute for a varied diet and a healthy lifestyle.\n• Consult a healthcare professional before use if pregnant, nursing, taking medication or under medical supervision.\n• Do not exceed the recommended dose.\n• Keep out of reach of children.\n• Store in a cool, dry place away from direct sunlight."}$c$::jsonb)
